// Generate a random 16-bit value and convert to little-endian
uint16_t x = (uint16_t)(*FUZZ_PARAM(unsigned int) & 0xFFFF);
uint16_t y = libusb_cpu_to_le16(x);
// Property: converting twice (on any-endian via swap/no-op) should yield the same value when reinterpreted appropriately.
// We don't assert here since endianness depends on host; just exercise the helper.

// Initialize a new libusb context. We pass a non-NULL receiver to get an explicit context
libusb_context *ctx = nullptr;
int rc = libusb_init(&ctx);
if (rc != 0 || !ctx) { FUZZ_BAIL(); }
// Track that this context is initialized and usable
FUZZ_SET_ATTR_INT(ctx, "initialized", 1);

// Build a small options array with valid entries
struct libusb_init_option opts[2];
// Option 0: log level
opts[0].option = LIBUSB_OPTION_LOG_LEVEL;
opts[0].value.ival = (int)(*FUZZ_PARAM(unsigned int) % 5); // 0..4
// Option 1: log callback cleared (NULL)
opts[1].option = LIBUSB_OPTION_LOG_CB;
opts[1].value.log_cbval = nullptr;
libusb_context *ctx = nullptr;
int num_options = 2;
int rc = libusb_init_context(&ctx, opts, num_options);
if (rc != 0 || !ctx) { FUZZ_BAIL(); }
FUZZ_SET_ATTR_INT(ctx, "initialized", 1);
FUZZ_SET_ATTR_INT(ctx, "log_level", opts[0].value.ival);

// Deinitialize and free a libusb context. After this call, ctx must not be used.
// We assume the input ctx was previously initialized.
libusb_exit(ctx);
// Do not return ctx as an output to avoid use-after-free.

// Set a debug level between NONE(0) and DEBUG(4)
int level = (int)(*FUZZ_PARAM(unsigned int) % 5);
libusb_set_debug(ctx, level);
FUZZ_SET_ATTR_INT(ctx, "log_level", level);

// Install (or clear) a log callback for the given context. We clear it to avoid defining functions in the stub.
libusb_log_cb cb = nullptr; // clearing callback is valid
int mode_bits = (int)(*FUZZ_PARAM(unsigned int) % 4); // 0..3 combinations of GLOBAL/CONTEXT
int mode = 0;
if (mode_bits & 1) mode |= LIBUSB_LOG_CB_GLOBAL;
if (mode_bits & 2) mode |= LIBUSB_LOG_CB_CONTEXT;
libusb_set_log_cb(ctx, cb, mode);
// Track chosen mode (for information only)
FUZZ_SET_ATTR_INT(ctx, "log_cb_mode", mode);

// Retrieve the static version structure; pointer must not be freed
const struct libusb_version *v = libusb_get_version();
if (!v) { FUZZ_BAIL(); }
// Cast-away const for the fuzzer pool type compatibility; do not modify contents
struct libusb_version *version = (struct libusb_version *)v; // safe aliasing for pool tracking only
FUZZ_SET_ATTR_STR(version, "ownership", "libusb_static");

// Query a capability supported by the backend
unsigned int cap_index = *FUZZ_PARAM(unsigned int) % 4; // pick among a few known caps
uint32_t capability = 0;
switch (cap_index) {
  case 0: capability = LIBUSB_CAP_HAS_CAPABILITY; break;
  case 1: capability = LIBUSB_CAP_HAS_HOTPLUG; break;
  case 2: capability = LIBUSB_CAP_HAS_HID_ACCESS; break;
  default: capability = LIBUSB_CAP_SUPPORTS_DETACH_KERNEL_DRIVER; break;
}
(void)libusb_has_capability(capability);

// Set locale for error strings; use a fuzzed locale-like token
std::string loc = FUZZ_PARAM_STR();
// Limit length to avoid excessively large allocations
if (loc.size() > 32) loc.resize(32);
// Ensure it is a C-style string
int rc = libusb_setlocale(loc.c_str());
(void)rc;

// Enumerate devices; keep the returned list pointer and optionally a device
libusb_device **list = nullptr;
ssize_t cnt = libusb_get_device_list(ctx, &list);
if (cnt < 0 || !list) { FUZZ_BAIL(); }
// We will retain the first device pointer (if any) by freeing the list with unref_devices=0 later.
libusb_device *dev0 = nullptr;
int retain = 0;
if (cnt > 0 && list[0] != nullptr) {
  dev0 = list[0];
  retain = 1;
  // Track a synthetic refcount for fuzz bookkeeping
  FUZZ_SET_ATTR_INT(dev0, "refcount", FUZZ_GET_ATTR_INT(dev0, "refcount") + 1);
  FUZZ_SET_ATTR_STR(dev0, "origin", "device_list");
}
void *dev_list_handle = (void*)list; // store the actual list pointer in the handle value
// Tag attributes on the handle to validate correct freeing later
FUZZ_SET_ATTR_STR(dev_list_handle, "type", "device_list");
FUZZ_SET_ATTR_INT(dev_list_handle, "retain_first", retain);
FUZZ_SET_ATTR_INT(dev_list_handle, "count", (int)cnt);
// If no device was present, still output a non-null dev0? No, keep it null by not returning it.
if (!dev0) {
  // Provide a dummy device pointer as null is not allowed for outputs; instead, skip returning dev0 by bailing.
  // However, outputs list requires dev0; ensure we set it to a valid value when none present by creating a ref if possible.
  // If there are zero devices, we cannot fabricate one; in that case, just set dev0 to the first (which is nullptr) and proceed.
}
// Note: dev0 may be nullptr if no devices are present; the fuzzer runtime will avoid using null objects.

// Free a device list previously returned by libusb_get_device_list
const char *ty = FUZZ_GET_ATTR_STR(dev_list_handle, "type");
int is_device_list = (ty && ty[0]) ? 1 : 0;
if (!is_device_list) { FUZZ_BAIL(); }
libusb_device **list = (libusb_device **)dev_list_handle;
int retain = FUZZ_GET_ATTR_INT(dev_list_handle, "retain_first");
int unref_devices = retain ? 0 : (int)(*FUZZ_PARAM(unsigned int) & 1);
libusb_free_device_list(list, unref_devices);
// Drop the handle by not returning it.

// Increase the device reference count
libusb_device *out = libusb_ref_device(dev);
if (!out) { FUZZ_BAIL(); }
FUZZ_SET_ATTR_INT(out, "refcount", FUZZ_GET_ATTR_INT(out, "refcount") + 1);
// Return the same device as output to keep it alive
libusb_device *dev_ret = out;
// Reassign output variable name
dev = dev_ret;

// Decrease the device reference count; it may free the device internally
int rcnt = FUZZ_GET_ATTR_INT(dev, "refcount");
if (rcnt > 0) { FUZZ_SET_ATTR_INT(dev, "refcount", rcnt - 1); }
libusb_unref_device(dev);
// Do not return the device to avoid use-after-free if refcount reached zero.

// Fetch a device string into a writable buffer
int which = (int)(*FUZZ_PARAM(unsigned int) % LIBUSB_DEVICE_STRING_COUNT);
enum libusb_device_string_type string_type = (enum libusb_device_string_type)which;
int length = 256; // sufficient for most strings
std::string tmp = FUZZ_PARAM_STR();
if ((int)tmp.size() < length) tmp.resize(length, '\0');
int wrote = libusb_get_device_string(dev, string_type, &tmp[0], length);
(void)wrote;
// Return dev unchanged as an output to keep it in the pool

// Open a device to obtain a handle, query configuration, then close
libusb_device_handle *handle = nullptr;
int orc = libusb_open(dev, &handle);
if (orc != 0 || !handle) { FUZZ_BAIL(); }
int config = -1;
(void)libusb_get_configuration(handle, &config);
libusb_close(handle);
// Return dev unchanged

// Retrieve the device descriptor
struct libusb_device_descriptor desc;
int rc = libusb_get_device_descriptor(dev, &desc);
(void)rc; // errors are allowed; we only enforce API contract
// Keep dev alive by returning it

// Get the active configuration descriptor; on success, it must later be freed
struct libusb_config_descriptor *config = nullptr;
int rc = libusb_get_active_config_descriptor(dev, &config);
if (rc != 0 || !config) { FUZZ_BAIL(); }
// Tag ownership for later freeing
FUZZ_SET_ATTR_STR(config, "owner", "libusb");
// Return both dev and config

// Get a configuration descriptor by index
uint8_t config_index = (uint8_t)(*FUZZ_PARAM(unsigned int) % 4); // small index range
struct libusb_config_descriptor *config = nullptr;
int rc = libusb_get_config_descriptor(dev, config_index, &config);
if (rc != 0 || !config) { FUZZ_BAIL(); }
FUZZ_SET_ATTR_INT(config, "config_index", (int)config_index);
FUZZ_SET_ATTR_STR(config, "owner", "libusb");

// Map an error code to its constant name string using valid enum values
int codes[] = {LIBUSB_SUCCESS, LIBUSB_ERROR_IO, LIBUSB_ERROR_INVALID_PARAM, LIBUSB_ERROR_ACCESS, LIBUSB_ERROR_NO_DEVICE, LIBUSB_ERROR_NOT_FOUND, LIBUSB_ERROR_BUSY, LIBUSB_ERROR_TIMEOUT, LIBUSB_ERROR_OVERFLOW, LIBUSB_ERROR_PIPE, LIBUSB_ERROR_INTERRUPTED, LIBUSB_ERROR_NO_MEM, LIBUSB_ERROR_NOT_SUPPORTED, LIBUSB_ERROR_OTHER};
int idx = (int)(*FUZZ_PARAM(unsigned int) % (int)(sizeof(codes)/sizeof(codes[0])));
int err = codes[idx];
const char *name = libusb_error_name(err);
(void)name;
// Validation: we exercised the mapping for a valid libusb_error value.

// Map an error code to a human-readable string using valid enum values
int codes[] = {LIBUSB_SUCCESS, LIBUSB_ERROR_IO, LIBUSB_ERROR_INVALID_PARAM, LIBUSB_ERROR_ACCESS, LIBUSB_ERROR_NO_DEVICE, LIBUSB_ERROR_NOT_FOUND, LIBUSB_ERROR_BUSY, LIBUSB_ERROR_TIMEOUT, LIBUSB_ERROR_OVERFLOW, LIBUSB_ERROR_PIPE, LIBUSB_ERROR_INTERRUPTED, LIBUSB_ERROR_NO_MEM, LIBUSB_ERROR_NOT_SUPPORTED, LIBUSB_ERROR_OTHER};
int idx = (int)(*FUZZ_PARAM(unsigned int) % (int)(sizeof(codes)/sizeof(codes[0])));
int err = codes[idx];
const char *s = libusb_strerror(err);
(void)s;
// Validation: we exercised the mapping for a valid libusb_error value.

// Retrieve a configuration descriptor by bConfigurationValue
uint8_t bConfigurationValue = (uint8_t)(*FUZZ_PARAM(unsigned int) & 0xFF);
struct libusb_config_descriptor *config = nullptr;
int rc = libusb_get_config_descriptor_by_value(dev, bConfigurationValue, &config);
if (rc != 0 || !config) { FUZZ_BAIL(); }
// Track ownership for later free
FUZZ_SET_ATTR_STR(config, "owner", "libusb");
FUZZ_SET_ATTR_INT(config, "bConfigurationValue", (int)bConfigurationValue);
// Outputs: keep dev alive and return the allocated config
// Validation: successful call implies config is valid and must be freed later.

// Free a configuration descriptor previously allocated by a libusb_get_*_config_descriptor call
libusb_free_config_descriptor(config);
// Do not return config to avoid use-after-free
// Validation: matching free for previously allocated descriptor.

// Parse and return the SS endpoint companion descriptor for an endpoint within the provided config
// We derive a valid endpoint descriptor from the config's first interface/altsetting/endpoint
if (!config || config->bNumInterfaces == 0 || !config->interface) { FUZZ_BAIL(); }
const struct libusb_interface *ifs = config->interface;
int if_idx = 0;
const struct libusb_interface_descriptor *alt = nullptr;
if (ifs[if_idx].num_altsetting <= 0 || !ifs[if_idx].altsetting) { FUZZ_BAIL(); }
alt = &ifs[if_idx].altsetting[0];
if (alt->bNumEndpoints == 0 || !alt->endpoint) { FUZZ_BAIL(); }
const struct libusb_endpoint_descriptor *ep = &alt->endpoint[0];
struct libusb_ss_endpoint_companion_descriptor *ep_comp = nullptr;
int rc = libusb_get_ss_endpoint_companion_descriptor(ctx, ep, &ep_comp);
if (rc != 0 || !ep_comp) { FUZZ_BAIL(); }
// Tag ownership for later free
FUZZ_SET_ATTR_STR(ep_comp, "owner", "libusb");
// Outputs: keep config (input, still valid) and provide ep_comp for later freeing
// Validation: ensured presence of an endpoint before calling; successful parse yields alloc to be freed later.

// Free a SuperSpeed Endpoint Companion descriptor
libusb_free_ss_endpoint_companion_descriptor(ep_comp);
// Validation: corresponding free for prior allocation.

// Open the device to retrieve the BOS descriptor
libusb_device_handle *handle = nullptr;
int orc = libusb_open(dev, &handle);
if (orc != 0 || !handle) { FUZZ_BAIL(); }
struct libusb_bos_descriptor *bos = nullptr;
int rc = libusb_get_bos_descriptor(handle, &bos);
// Close the transient handle regardless of success
libusb_close(handle);
if (rc != 0 || !bos) { FUZZ_BAIL(); }
// Track ownership for later free
FUZZ_SET_ATTR_STR(bos, "owner", "libusb");
// Output dev (still valid) and bos (allocated)
// Validation: ensures handle lifecycle is balanced and bos is returned for later free.

// Free a BOS descriptor previously obtained
libusb_free_bos_descriptor(bos);
// Validation: proper matching free for BOS descriptor.

// Find a BOS device capability of type USB 2.0 Extension and parse it
if (!bos || bos->bNumDeviceCaps == 0) { FUZZ_BAIL(); }
struct libusb_bos_dev_capability_descriptor *chosen = nullptr;
for (uint8_t i = 0; i < bos->bNumDeviceCaps; ++i) {
  struct libusb_bos_dev_capability_descriptor *dc = bos->dev_capability[i];
  if (!dc) continue;
